      es: ["Las torres gemelas alcanzan una altura arquitectónica total de 451,9 metros.", "La inauguración oficial de las Torres Petronas tuvo lugar el 31 de agosto de 1999.", "Cada una de las dos torres pesa aproximadamente 300.000 toneladas.", "El puente de conexión (Skybridge) se encuentra exactamente a 170 metros de altura.", "Los edificios poseen los cimientos más profundos del mundo, con hasta 120 metros de profundidad.", "Se tardó exactamente seis años en completar este gigantesco proyecto de construcción."],
      pt: ["As torres gémeas atingem uma altura arquitetónica total de 451,9 metros.", "A abertura oficial das Petronas Twin Towers ocorreu em 31 de agosto de 1999.", "Cada uma das duas torres pesa cerca de 300.000 toneladas.", "A ponte de ligação (Skybridge) situa-se exatamente a 170 metros de altura.", "Os edifícios possuem a fundação mais profunda conhecida no mundo, com até 120 metros de profundidade.", "Foram necessários exatamente seis anos para concluir o gigantesco projeto de construção."],
      fr: ["Les tours jumelles atteignent une hauteur architecturale totale de 451,9 mètres.", "L'ouverture officielle des tours Petronas a eu lieu le 31 août 1999.", "Chacune des deux tours pèse environ 300 000 tonnes.", "La passerelle de liaison (Skybridge) se situe exactement à 170 mètres de hauteur.", "Les bâtiments possèdent les fondations les plus profondes au monde, atteignant 120 mètres de profondeur.", "Il a fallu exactement six ans pour achever ce gigantesque projet de construction."],
